panels.css:
main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:64px 60px 0;background:radial-gradient(circle at 10% 20%,rgba(214,62,118,.12),transparent 45%),radial-gradient(circle at 92% 80%,rgba(245,197,24,.16),transparent 48%),var(--cream)}
.k{font-size:32px;font-weight:700;color:var(--ink-2);text-align:center}
.t{font-size:66px;font-weight:900;line-height:1.25;text-align:center;margin-top:10px}
.t em{font-style:normal;color:#D63E76}
.one{position:absolute;left:60px;right:60px;bottom:64px;text-align:center;font-size:34px;font-weight:700;background:#46293A;color:#fff;border-radius:18px;padding:22px 16px}.one b{color:#F5C518;font-weight:900}
.tl{margin-top:40px;background:#fff;border-radius:26px;padding:10px 30px;box-shadow:0 20px 40px -26px rgba(30,18,25,.4)}
.r{display:grid;grid-template-columns:110px 170px 1fr;align-items:center;gap:18px;padding:22px 0;border-bottom:2px dashed #eadde3}.r:last-child{border-bottom:0}
.d{font-size:38px;font-weight:900;color:#D63E76}
.lg{height:90px;display:flex;align-items:center;justify-content:center;background:#fff;border:2px solid #eadde3;border-radius:14px;padding:8px}
.lg img{max-width:100%;max-height:72px;object-fit:contain}.lg img.sm{width:140px;max-height:none}
.tx{font-size:34px;font-weight:700}.tx b{display:block;font-size:26px;color:var(--ink-2);margin-bottom:2px}
.tx s{color:#9a8790}.tx em{font-style:normal;color:#D63E76;font-weight:900;font-size:42px}
.tx small{display:block;font-size:24px;color:var(--ink-2);margin-top:2px}
